// ดึงเลขเอกสารจากหัวข้ออีเมล และแปลงไฟล์แนบเป็น base64
const subject = $json.subject ?? '';
const docNo = (subject.match(/(\d{9,12})/) || [])[1];
if (!docNo) {
  throw new Error('หาเลขเอกสารในหัวข้อไม่เจอ: ' + subject);
}

// หาไฟล์แนบ .pdf ตัวแรก
const binaryKeys = Object.keys($binary ?? {});
const pdfKey = binaryKeys.find((k) => ($binary[k].fileName ?? '').toLowerCase().endsWith('.pdf'));
if (!pdfKey) {
  throw new Error('ไม่พบไฟล์แนบ .pdf ในอีเมลเลขที่ ' + docNo);
}

const file = await this.helpers.getBinaryDataBuffer(0, pdfKey);

return {
  json: {
    documentNo: docNo,
    fileName: $binary[pdfKey].fileName,
    fileBase64: file.toString('base64'),
    sourceEmailId: $json.id ?? null,
    receivedAt: $json.date ?? new Date().toISOString(),
    approvedBy: 'Project Manager (TLI)',
    actor: 'n8n'
  }
};
